namespace {

const json kSample = json::parse(R"({
  "$schema": "http://json-schema.org/draft-07/schema#",
  "type": "object",
  "required": ["name"],
  "properties": {
    "name": {"type": "string"},
    "gain": {"type": "number", "minimum": 0, "maximum": 1, "default": 0.5},
    "options": {
      "type": "object",
      "properties": {"retries": {"type": "integer", "default": 3}},
      "additionalProperties": false
    }
  },
  "additionalProperties": false
})");

template <typename Fn> ErrorCode error_code_of(Fn&& fn) {
    try {
        fn();
    } catch (const Error& e) {
        return e.code();
    }
    return ErrorCode::OK;
}

std::string read_bytes(const fs::path& path) {
    std::ifstream in(path, std::ios::binary);
    return std::string(std::istreambuf_iterator<char>(in), std::istreambuf_iterator<char>());
}

void write_file(const fs::path& path, const std::string& text) {
    std::ofstream out(path, std::ios::binary);
    out << text;
}

} // namespace

TEST(Schema, ValidReturnsNoIssues) {
    const CompiledSchema schema(kSample, "sample");
    EXPECT_EQ(schema.name(), "sample");
    EXPECT_TRUE(schema.validate(json::parse(R"({"name":"x","gain":0.25})")).empty());
    EXPECT_TRUE(schema.validate(json::parse(R"({"name":"x","options":{"retries":1}})")).empty());
}

TEST(Schema, InvalidReturnsPointersAndMessages) {
    const CompiledSchema schema(kSample, "sample");
    const auto issues = schema.validate(json::parse(R"({"name":"x","gain":-1})"));
    ASSERT_EQ(issues.size(), 1u);
    EXPECT_EQ(issues[0].pointer, "/gain");
    EXPECT_NE(issues[0].message.find("Minimum value is 0"), std::string::npos) << issues[0].message;

    // Every problem is collected, not only the first.
    const auto many = schema.validate(json::parse(R"({"gain":"high","options":{"retries":1.5}})"));
    std::set<std::string> pointers;
    for (const auto& issue : many) {
        pointers.insert(issue.pointer);
        EXPECT_FALSE(issue.message.empty());
    }
    EXPECT_EQ(pointers, (std::set<std::string>{"", "/gain", "/options/retries"}));

    // A property that `additionalProperties` forbids is reported at the property itself.
    const auto unknown =
        schema.validate(json::parse(R"({"name":"x","extra":1,"options":{"x/y":2}})"));
    ASSERT_EQ(unknown.size(), 2u);
    EXPECT_EQ(unknown[0].pointer, "/extra");
    EXPECT_EQ(unknown[0].message, "property 'extra' is not allowed");
    EXPECT_EQ(unknown[1].pointer, "/options/x~1y");

    const auto root = schema.validate(json::parse("[1, 2]"));
    ASSERT_FALSE(root.empty());
    EXPECT_EQ(root[0].pointer, "");
}

TEST(Schema, DefaultsApplied) {
    const CompiledSchema schema(kSample, "sample");
    std::vector<SchemaIssue> issues;
    const auto completed = schema.apply_defaults(json::parse(R"({"name":"x"})"), issues);
    EXPECT_TRUE(issues.empty());
    EXPECT_EQ(completed.at("gain"), json(0.5));
    EXPECT_EQ(completed.at("name"), json("x"));

    // Given values are kept; defaults of nested objects that are present are filled in.
    const auto nested =
        schema.apply_defaults(json::parse(R"({"name":"x","gain":0.9,"options":{}})"), issues);
    EXPECT_TRUE(issues.empty());
    EXPECT_EQ(nested.at("gain"), json(0.9));
    EXPECT_EQ(nested.at("options").at("retries"), json(3));

    // Problems are reported through `issues`.
    schema.apply_defaults(json::parse(R"({"gain":2})"), issues);
    EXPECT_EQ(issues.size(), 2u);
}

TEST(Schema, InvalidSchemaThrowsSchemaViolation) {
    const std::vector<std::string> bad = {
        R"({"type": "numbr"})",
        R"({"type": 5})",
        R"({"minimum": "zero"})",
        R"({"properties": []})",
        R"({"required": "name"})",
        R"({"pattern": "("})",
        R"({"$ref": "#/definitions/missing"})",
        R"({"$ref": "http://example.com/other.json"})",
        R"({"$ref": "urn:praenora:schema:no-such-kind:0.1"})",
        R"({"$schema": "http://json-schema.org/draft-04/schema#", "type": "object"})",
        R"({"$schema": "https://json-schema.org/draft/2019-09/schema", "type": "object"})",
        R"({"$schema": "https://example.com/not-a-dialect", "type": "object"})",
        R"({"$schema": 5})",
        R"({"$ref": "#"})",
        R"({"$id": 7})",
        R"(42)",
        R"("object")",
    };
    for (const auto& text : bad) {
        SCOPED_TRACE(text);
        EXPECT_EQ(error_code_of([&] { CompiledSchema(json::parse(text), "bad"); }),
                  ErrorCode::SCHEMA_VIOLATION);
    }
    try {
        CompiledSchema(json::parse(R"({"type": "object", "properties": {"a": {"type": "numbr"}}})"),
                       "params");
        FAIL() << "no error";
    } catch (const Error& e) {
        EXPECT_NE(std::string(e.what()).find("params"), std::string::npos) << e.what();
        EXPECT_EQ(e.location().pointer, "/properties/a");
    }
}

TEST(Schema, UrnIdAccepted) {
    const auto schema_json = json::parse(R"({
      "$schema": "http://json-schema.org/draft-07/schema",
      "$id": "urn:praenora:schema:sample:0.1",
      "type": "object",
      "properties": {"gain": {"$ref": "#/definitions/fraction"}},
      "definitions": {"fraction": {"type": "number", "minimum": 0, "maximum": 1}}
    })");
    const CompiledSchema schema(schema_json, "sample@0.1");
    EXPECT_TRUE(schema.validate(json::parse(R"({"gain":0.5})")).empty());
    const auto issues = schema.validate(json::parse(R"({"gain":1.5})"));
    ASSERT_EQ(issues.size(), 1u);
    EXPECT_EQ(issues[0].pointer, "/gain");
}

TEST(Schema, BooleanSchemasAndDraft07MetaSchemaReference) {
    EXPECT_TRUE(CompiledSchema(json(true), "any").validate(json::parse("[1]")).empty());
    EXPECT_FALSE(CompiledSchema(json(false), "none").validate(json::parse("1")).empty());
    // A schema may describe schemas by referring to the draft-07 meta-schema.
    const CompiledSchema schemas(
        json::parse(R"({"$ref": "http://json-schema.org/draft-07/schema#"})"), "schema");
    EXPECT_TRUE(schemas.validate(kSample).empty());
    EXPECT_FALSE(schemas.validate(json::parse(R"({"type": "numbr"})")).empty());
}

TEST(Schema, FormatsAreCheckedWhenSupported) {
    const CompiledSchema date_time(json::parse(R"({"type":"string","format":"date-time"})"), "dt");
    EXPECT_TRUE(date_time.validate(json("2026-11-10T16:04:05.123456789Z")).empty());
    EXPECT_FALSE(date_time.validate(json("yesterday")).empty());
    // A format the validator does not implement is accepted (formats are annotations then).
    const CompiledSchema reference(json::parse(R"({"type":"string","format":"uri-reference"})"),
                                   "ref");
    EXPECT_TRUE(reference.validate(json("a/b#c")).empty());
    const CompiledSchema unknown(json::parse(R"({"type":"string","format":"made-up"})"), "unknown");
    EXPECT_TRUE(unknown.validate(json("anything")).empty());
    const CompiledSchema uuid(json::parse(R"({"type":"string","format":"uuid"})"), "uuid");
    EXPECT_FALSE(uuid.validate(json("not a uuid")).empty());
}

// Formats are assertions in both dialects, although 2020-12 makes them annotations by default.
TEST(Schema, FormatsAreAssertionsInBothDialects) {
    for (const char* dialect : {"http://json-schema.org/draft-07/schema#",
                                "https://json-schema.org/draft/2020-12/schema"}) {
        SCOPED_TRACE(dialect);
        const json schema = {{"$schema", dialect}, {"type", "string"}, {"format", "date-time"}};
        const CompiledSchema compiled(schema, "dt");
        EXPECT_TRUE(compiled.validate(json("2026-11-10T16:04:05Z")).empty());
        EXPECT_FALSE(compiled.validate(json("yesterday")).empty());
        const json pointer = {{"$schema", dialect}, {"type", "string"}, {"format", "json-pointer"}};
        EXPECT_FALSE(CompiledSchema(pointer, "jp").validate(json("not/a/pointer")).empty());
    }
}

TEST(Schema, DialectIsSelectedBySchemaKeyword) {
    // Without `$schema` a schema is draft-07: `definitions` references resolve.
    const CompiledSchema plain(json::parse(R"({
      "definitions": {"n": {"type": "number"}},
      "properties": {"p": {"$ref": "#/definitions/n"}}})"),
                               "plain");
    EXPECT_FALSE(plain.validate(json::parse(R"({"p":"x"})")).empty());
    // 2020-12 knows `$defs`, and does not follow `definitions` unless asked.
    const CompiledSchema modern(json::parse(R"({
      "$schema": "https://json-schema.org/draft/2020-12/schema",
      "$defs": {"n": {"type": "number"}},
      "properties": {"p": {"$ref": "#/$defs/n"}}})"),
                                "modern");
    EXPECT_TRUE(modern.validate(json::parse(R"({"p":1})")).empty());
    EXPECT_FALSE(modern.validate(json::parse(R"({"p":"x"})")).empty());
    EXPECT_EQ(error_code_of([&] {
                  CompiledSchema(json::parse(R"({
                    "$schema": "https://json-schema.org/draft/2020-12/schema",
                    "definitions": {"n": {"type": "number"}},
                    "properties": {"p": {"$ref": "#/definitions/n"}}})"),
                                 "legacy");
              }),
              ErrorCode::SCHEMA_VIOLATION);
}

// Instances that violate 2020-12 keywords, which the previous validator accepted without a word.
TEST(Schema, Keywords2020AreEnforced) {
    const auto invalid = [](const char* schema_text, const char* instance_text) {
        json schema = json::parse(schema_text);
        schema["$schema"] = "https://json-schema.org/draft/2020-12/schema";
        return !CompiledSchema(schema, "modern").validate(json::parse(instance_text)).empty();
    };
    EXPECT_TRUE(invalid(R"({"prefixItems": [{"type": "string"}]})", "[1]"));
    EXPECT_FALSE(invalid(R"({"prefixItems": [{"type": "string"}]})", R"(["a", 1])"));
    EXPECT_TRUE(invalid(R"({"properties": {"a": {}}, "unevaluatedProperties": false})",
                        R"({"a": 1, "b": 2})"));
    EXPECT_FALSE(invalid(R"({"properties": {"a": {}}, "unevaluatedProperties": false})",
                         R"({"a": 1})"));
    EXPECT_TRUE(invalid(R"({"dependentRequired": {"a": ["b"]}})", R"({"a": 1})"));
    EXPECT_TRUE(invalid(R"({"$defs": {"n": {"type": "number"}},
                            "properties": {"p": {"$ref": "#/$defs/n", "maximum": 1}}})",
                        R"({"p": 5})"));
    EXPECT_TRUE(invalid(R"({"$id": "https://t/root", "$ref": "list", "$defs": {
        "foo": {"$dynamicAnchor": "items", "type": "string"},
        "list": {"$id": "list", "type": "array", "items": {"$dynamicRef": "#items"},
                 "$defs": {"items": {"$dynamicAnchor": "items"}}}}})",
                        R"(["foo", 42])"));
}

// Draft-07 ignores the keywords beside a $ref, 2020-12 applies them (and a default among them).
TEST(Schema, KeywordsBesideReferenceFollowTheDialect) {
    const char* const body = R"("definitions": {"n": {"type": "number"}},
                                "properties": {"p": {"$ref": "#/definitions/n", "maximum": 1}}})";
    const CompiledSchema draft07(json::parse(std::string(R"({)") + body), "d7");
    EXPECT_TRUE(draft07.validate(json::parse(R"({"p": 5})")).empty());
    const CompiledSchema modern(
        json::parse(std::string(R"({"$schema": "https://json-schema.org/draft/2020-12/schema",)") +
                    R"("$defs": {"n": {"type": "number"}},
                       "properties": {"p": {"$ref": "#/$defs/n", "maximum": 1, "default": 1}}})"),
        "modern");
    EXPECT_FALSE(modern.validate(json::parse(R"({"p": 5})")).empty());
    std::vector<SchemaIssue> issues;
    EXPECT_EQ(modern.apply_defaults(json::object(), issues).at("p"), json(1));

    const auto places = praenora::detail::ignored_ref_siblings(json::parse(std::string(R"({)") + body));
    ASSERT_EQ(places.size(), 1u);
    EXPECT_EQ(places[0], "/properties/p (maximum)");
    EXPECT_TRUE(praenora::detail::ignored_ref_siblings(
                    json::parse(R"({"$schema": "https://json-schema.org/draft/2020-12/schema",
                                    "properties": {"p": {"$ref": "#/$defs/n", "maximum": 1}},
                                    "$defs": {"n": {"type": "number"}}})"))
                    .empty());
    // Annotations beside a $ref are not reported.
    EXPECT_TRUE(praenora::detail::ignored_ref_siblings(
                    json::parse(R"({"definitions": {"n": {"type": "number"}},
                                    "properties": {"p": {"$ref": "#/definitions/n",
                                                         "description": "d"}}})"))
                    .empty());
}

// A default in the schema a property points at is applied to the absent property, in both dialects.
TEST(Schema, DefaultsBehindReferencesAreApplied) {
    const CompiledSchema draft07(json::parse(R"({
      "definitions": {"fraction": {"type": "number", "default": 0.5}},
      "properties": {"gain": {"$ref": "#/definitions/fraction"}}})"),
                                 "d7");
    std::vector<SchemaIssue> issues;
    EXPECT_EQ(draft07.apply_defaults(json::object(), issues).at("gain"), json(0.5));
    EXPECT_TRUE(issues.empty());
    EXPECT_EQ(draft07.apply_defaults(json::parse(R"({"gain": 0.25})"), issues).at("gain"), json(0.25));
    EXPECT_FALSE(draft07.validate(json::parse(R"({"gain": "x"})")).empty());
    const CompiledSchema modern(json::parse(R"({
      "$schema": "https://json-schema.org/draft/2020-12/schema",
      "$defs": {"fraction": {"type": "number", "default": 0.5}},
      "properties": {"gain": {"$ref": "#/$defs/fraction"}}})"),
                                "modern");
    EXPECT_EQ(modern.apply_defaults(json::object(), issues).at("gain"), json(0.5));
    // Nested defaults of a referenced object are filled in too.
    const CompiledSchema nested(json::parse(R"({
      "definitions": {"o": {"type": "object", "properties": {"r": {"default": 3}}}},
      "properties": {"a": {"$ref": "#/definitions/o"}}})"),
                                "nested");
    EXPECT_EQ(nested.apply_defaults(json::parse(R"({"a": {}})"), issues).at("a").at("r"), json(3));
}

// `integer` accepts a number with a zero fraction in both dialects, as the specification reads it.
TEST(Schema, IntegerAcceptsWholeDoubles) {
    for (const char* dialect : {"http://json-schema.org/draft-07/schema#",
                                "https://json-schema.org/draft/2020-12/schema"}) {
        SCOPED_TRACE(dialect);
        const CompiledSchema integer(json{{"$schema", dialect}, {"type", "integer"}}, "integer");
        EXPECT_TRUE(integer.validate(json::parse("1.0")).empty());
        EXPECT_TRUE(integer.validate(json::parse("3")).empty());
        EXPECT_FALSE(integer.validate(json::parse("1.5")).empty());
    }
}

// The first issue is the same in both dialects: issues come in pointer order, a parent first, array
// indices as numbers.
TEST(Schema, IssuesAreInPointerOrderInBothDialects) {
    const char* const body = R"("type": "object", "required": ["name"],
        "properties": {"steps": {"type": "array", "items": {"type": "integer"}},
                       "name": {"type": "string"}}})";
    const json instance = json::parse(R"({"steps": ["x",1,"y",3,4,5,6,7,8,9,"z"]})");
    std::vector<std::vector<std::string>> orders;
    for (const char* dialect : {"http://json-schema.org/draft-07/schema#",
                                "https://json-schema.org/draft/2020-12/schema"}) {
        const CompiledSchema schema(
            json::parse(std::string(R"({"$schema": ")") + dialect + R"(",)" + body), "ordered");
        std::vector<std::string> pointers;
        for (const auto& issue : schema.validate(instance)) {
            pointers.push_back(issue.pointer);
        }
        orders.push_back(pointers);
    }
    EXPECT_EQ(orders[0], orders[1]);
    EXPECT_EQ(orders[0], (std::vector<std::string>{"", "/steps/0", "/steps/2", "/steps/10"}));
}

// A schema that refers to itself without looking at the instance would overflow the stack of the
// validator; it is refused, and a schema that recurses through the instance is fine.
TEST(Schema, ReferenceCyclesAreRefusedAndTreesAreNot) {
    for (const char* text : {
             R"({"$ref": "#"})",
             R"({"$schema": "https://json-schema.org/draft/2020-12/schema", "$ref": "#"})",
             R"({"definitions": {"a": {"$ref": "#/definitions/b"}, "b": {"$ref": "#/definitions/a"}},
                 "$ref": "#/definitions/a"})",
             R"({"$schema": "https://json-schema.org/draft/2020-12/schema",
                 "$defs": {"a": {"$ref": "#/$defs/b"}, "b": {"$ref": "#/$defs/a"}},
                 "$ref": "#/$defs/a"})",
             R"({"allOf": [{"$ref": "#"}]})",
             R"({"definitions": {"a": {"anyOf": [{"type": "null"}, {"$ref": "#/definitions/a"}]}},
                 "$ref": "#/definitions/a"})",
         }) {
        SCOPED_TRACE(text);
        EXPECT_EQ(error_code_of([&] { CompiledSchema(json::parse(text), "cycle"); }),
                  ErrorCode::SCHEMA_VIOLATION);
    }
    const CompiledSchema tree(json::parse(R"({
      "definitions": {"node": {"type": "object", "properties": {
        "value": {"type": "integer"},
        "children": {"type": "array", "items": {"$ref": "#/definitions/node"}}}}},
      "$ref": "#/definitions/node"})"),
                              "tree");
    EXPECT_TRUE(tree.validate(json::parse(R"({"value": 1, "children": [{"value": 2}]})")).empty());
    const auto issues = tree.validate(json::parse(R"({"children": [{"children": [{"value": "x"}]}]})"));
    ASSERT_EQ(issues.size(), 1u);
    EXPECT_EQ(issues[0].pointer, "/children/0/children/0/value");
    const CompiledSchema recursive(json::parse(R"({"$id": "urn:x:tree", "type": "object",
      "properties": {"next": {"$ref": "#"}}})"),
                                   "recursive");
    EXPECT_FALSE(recursive.validate(json::parse(R"({"next": {"next": 1}})")).empty());
}

// An issue in the schema of `additionalProperties` is located at the property.
TEST(Schema, PropertyFailingAdditionalPropertiesSchemaIsLocatedAtTheProperty) {
    const CompiledSchema schema(json::parse(R"({"additionalProperties": {"type": "integer"}})"),
                                "map");
    const auto issues = schema.validate(json::parse(R"({"a": 1, "b/c": "x"})"));
    ASSERT_EQ(issues.size(), 1u);
    EXPECT_EQ(issues[0].pointer, "/b~1c");
}

TEST(Schema, ConcurrentValidationIsSafe) {
    const CompiledSchema schema(kSample, "sample");
    std::vector<std::thread> threads;
    std::vector<int> failures(8, 0);
    for (std::size_t t = 0; t < failures.size(); ++t) {
        threads.emplace_back([&, t] {
            for (int i = 0; i < 200; ++i) {
                if (!schema.validate(json::parse(R"({"name":"x","gain":0.5})")).empty() ||
                    schema.validate(json::parse(R"({"gain":-1})")).size() != 2) {
                    ++failures[t];
                }
            }
        });
    }
    for (auto& thread : threads) {
        thread.join();
    }
    for (const int f : failures) {
        EXPECT_EQ(f, 0);
    }
}

TEST(SchemaRegistry, FromDirectorySelectsByFormatVersion) {
    const auto registry =
        SchemaRegistry::from_directory(praenora::test::fixture_path("documents/schema-registry"));
    const auto& v01 = registry.for_kind("sample", parse_semver("0.1.7"));
    EXPECT_EQ(v01.name(), "sample@0.1");
    EXPECT_NE(registry.text_for_kind("sample", parse_semver("0.1.0"))
                  .find("urn:praenora:schema:sample:0.1"),
              std::string_view::npos);
    // 0.1 has no "mode"; 0.2 adds it with a default.
    std::vector<SchemaIssue> issues;
    EXPECT_FALSE(v01.validate(json::parse(R"({"name":"x","mode":"fast"})")).empty());
    const auto& v02 = registry.for_kind("sample", parse_semver("0.2.0-rc.1"));
    EXPECT_EQ(v02.name(), "sample@0.2");
    const auto completed = v02.apply_defaults(json::parse(R"({"name":"x"})"), issues);
    EXPECT_TRUE(issues.empty());
    EXPECT_EQ(completed.at("mode"), json("exact"));
    EXPECT_EQ(completed.at("gain"), json(0.5)) << "defaults are found through $ref";

    // The same compiled schema is returned every time.
    EXPECT_EQ(&registry.for_kind("sample", parse_semver("0.1.0")), &v01);

    EXPECT_EQ(error_code_of([&] { registry.for_kind("sample", parse_semver("0.3.0")); }),
              ErrorCode::FORMAT_VERSION_UNSUPPORTED);
    EXPECT_EQ(error_code_of([&] { registry.for_kind("sample", parse_semver("1.1.0")); }),
              ErrorCode::FORMAT_VERSION_UNSUPPORTED);
    EXPECT_EQ(error_code_of([&] { registry.for_kind("other", parse_semver("0.1.0")); }),
              ErrorCode::FORMAT_VERSION_UNSUPPORTED);
    EXPECT_EQ(error_code_of([&] { registry.text_for_kind("sample", parse_semver("0.3.0")); }),
              ErrorCode::FORMAT_VERSION_UNSUPPORTED);
}

TEST(SchemaRegistry, EntriesAreSortedByKindAndVersion) {
    const auto registry =
        SchemaRegistry::from_directory(praenora::test::fixture_path("documents/schema-registry"));
    const auto entries = registry.entries();
    ASSERT_EQ(entries.size(), 2u);
    EXPECT_EQ(entries[0].first, "sample");
    EXPECT_EQ(praenora::detail::to_string(entries[0].second), "0.1.0");
    EXPECT_EQ(praenora::detail::to_string(entries[1].second), "0.2.0");
}

TEST(SchemaRegistry, SchemaIdMustMatchItsFileName) {
    ScratchDir dir;
    write_file(dir.path() / "other.0.1.schema.json",
               R"({"$id": "urn:praenora:schema:sample:0.1", "type": "object"})");
    write_file(dir.path() / "broken.0.1.schema.json", "{ not json");
    write_file(dir.path() / "anonymous.0.1.schema.json", R"({"type": "object"})");
    write_file(dir.path() / "notes.txt", "ignored");
    write_file(dir.path() / "Bad_Name.0.1.schema.json", "{}");
    const auto registry = SchemaRegistry::from_directory(dir.path());
    EXPECT_EQ(registry.entries().size(), 3u) << "only <kind>.<major>.<minor>.schema.json files";
    EXPECT_EQ(error_code_of([&] { registry.for_kind("other", parse_semver("0.1.0")); }),
              ErrorCode::SCHEMA_VIOLATION);
    EXPECT_EQ(error_code_of([&] { registry.for_kind("anonymous", parse_semver("0.1.0")); }),
              ErrorCode::SCHEMA_VIOLATION)
        << "a registry schema must have an $id";
    EXPECT_EQ(error_code_of([&] { registry.for_kind("broken", parse_semver("0.1.0")); }),
              ErrorCode::PARSE_ERROR);
    EXPECT_EQ(error_code_of([&] { SchemaRegistry::from_directory(dir.path() / "missing"); }),
              ErrorCode::IO_ERROR);
}

TEST(SchemaRegistry, ConcurrentFirstUseCompilesOnce) {
    const auto registry =
        SchemaRegistry::from_directory(praenora::test::fixture_path("documents/schema-registry"));
    std::vector<const CompiledSchema*> seen(8, nullptr);
    std::vector<std::thread> threads;
    for (std::size_t t = 0; t < seen.size(); ++t) {
        threads.emplace_back(
            [&, t] { seen[t] = &registry.for_kind("sample", parse_semver("0.2.0")); });
    }
    for (auto& thread : threads) {
        thread.join();
    }
    for (const auto* schema : seen) {
        EXPECT_EQ(schema, seen[0]);
    }
}

