// Reference cycles through anchors, dynamic references and nested identifiers, which the walk has to
// resolve (or refuse); a library would overflow the stack on each.
TEST(Schema, CyclesThroughAnchorsDynamicReferencesAndNestedIdsAreRefused) {
    for (const char* text : {
             // an anchor that names its own schema
             R"({"$schema": "https://json-schema.org/draft/2020-12/schema", "$anchor": "a", "$ref": "#a"})",
             // a draft-07 plain-name identifier that names its own schema
             R"({"$id": "#a", "$ref": "#a"})",
             // two anchors that refer to each other
             R"({"$schema": "https://json-schema.org/draft/2020-12/schema",
                 "$defs": {"x": {"$anchor": "x", "$ref": "#y"}, "y": {"$anchor": "y", "$ref": "#x"}},
                 "$ref": "#x"})",
             // a dynamic reference to its own anchor
             R"({"$schema": "https://json-schema.org/draft/2020-12/schema",
                 "$dynamicAnchor": "n", "$dynamicRef": "#n"})",
             // a nested resource that refers to itself by its relative identifier
             R"({"$schema": "https://json-schema.org/draft/2020-12/schema",
                 "$id": "https://example.com/root",
                 "$defs": {"inner": {"$id": "inner", "$ref": "inner"}},
                 "$ref": "inner"})",
             // a reference through an absolute identifier of a nested resource
             R"({"$defs": {"a": {"$id": "https://example.com/a", "$ref": "https://example.com/a"}},
                 "$ref": "https://example.com/a"})",
         }) {
        SCOPED_TRACE(text);
        EXPECT_EQ(error_code_of([&] { CompiledSchema(json::parse(text), "cycle"); }),
                  ErrorCode::SCHEMA_VIOLATION);
    }
    // Recursion through the instance by anchor, dynamic reference or nested identifier is fine.
    const CompiledSchema anchored(json::parse(R"({
      "$schema": "https://json-schema.org/draft/2020-12/schema",
      "$anchor": "node", "type": "object",
      "properties": {"next": {"$ref": "#node"}, "later": {"$dynamicRef": "#node"}}})"),
                                  "anchored");
    EXPECT_TRUE(anchored.validate(json::parse(R"({"next": {"next": {}}})")).empty());
    EXPECT_FALSE(anchored.validate(json::parse(R"({"next": {"next": 1}})")).empty());
    const CompiledSchema nested(json::parse(R"({
      "$schema": "https://json-schema.org/draft/2020-12/schema",
      "$id": "https://example.com/root",
      "$ref": "tree",
      "$defs": {"tree": {"$id": "tree", "type": "object",
                         "properties": {"kid": {"$ref": "tree"}}}}})"),
                                "nested");
    EXPECT_FALSE(nested.validate(json::parse(R"({"kid": {"kid": 1}})")).empty());
}

TEST(Schema, UnresolvableReferencesAndEndlessChainsAreRefused) {
    for (const char* text : {
             R"({"$ref": "#nowhere"})",
             R"({"$schema": "https://json-schema.org/draft/2020-12/schema", "$ref": "#nowhere"})",
             R"({"$ref": "https://example.com/not-here.json#/x"})",
         }) {
        SCOPED_TRACE(text);
        EXPECT_EQ(error_code_of([&] { CompiledSchema(json::parse(text), "dangling"); }),
                  ErrorCode::SCHEMA_VIOLATION);
    }
}

TEST(Schema, AnEndlessChainOfReferencesIsRefused) {
    // A chain of references longer than the walk's limit is refused, not silently cut short.
    json chain = {{"$ref", "#/definitions/d0"}};
    json definitions = json::object();
    for (int i = 0; i < 300; ++i) {
        definitions["d" + std::to_string(i)] =
            i == 299 ? json{{"type", "string"}}
                     : json{{"$ref", "#/definitions/d" + std::to_string(i + 1)}};
    }
    chain["definitions"] = definitions;
    EXPECT_EQ(error_code_of([&] { CompiledSchema(chain, "chain"); }), ErrorCode::SCHEMA_VIOLATION);
}

TEST(Schema, ASchemaNestedTooDeepIsRefused) {
    json deep = {{"type", "string"}};
    for (int i = 0; i < 300; ++i) {
        deep = json{{"properties", {{"p", deep}}}};
    }
    EXPECT_EQ(error_code_of([&] { CompiledSchema(deep, "deep"); }), ErrorCode::SCHEMA_VIOLATION);
}

// The default behind a reference is computed on the side: what validates, and so what is reported
// first, is the schema as written.
TEST(Schema, DefaultBehindReferenceDoesNotChangeTheIssues) {
    const auto first_message = [](const char* fraction) {
        const CompiledSchema schema(json::parse(std::string(R"({
          "definitions": {"fraction": )") + fraction + R"(},
          "type": "object",
          "properties": {"gain": {"$ref": "#/definitions/fraction"}}})"),
                                    "gain");
        const auto issues = schema.validate(json::parse(R"({"gain": 2})"));
        return issues.empty() ? std::string("none")
                              : issues.front().pointer + " | " + issues.front().message;
    };
    const std::string without = first_message(R"({"type": "number", "maximum": 1})");
    const std::string with = first_message(R"({"type": "number", "maximum": 1, "default": 0.5})");
    EXPECT_EQ(without, with);
    EXPECT_NE(with.find("Maximum value is 1"), std::string::npos) << with;
}

// The order of pointers is a strict weak ordering: numbers before other names, numbers by value.
TEST(Schema, MixedKeysAreOrderedConsistently) {
    const CompiledSchema schema(
        json::parse(R"({"type": "object", "additionalProperties": {"type": "integer"}})"), "keys");
    json instance = json::object();
    for (const char* key : {"2", "10", "1a", "b", "1", "a", "20", "02"}) {
        instance[key] = "x";
    }
    std::vector<std::string> pointers;
    for (const auto& issue : schema.validate(instance)) {
        pointers.push_back(issue.pointer);
    }
    EXPECT_EQ(pointers,
              (std::vector<std::string>{"/1", "/2", "/02", "/10", "/20", "/1a", "/a", "/b"}));
}

// Several issues at one pointer come in the same order in both dialects.
TEST(Schema, IssuesAtOnePointerDoNotDependOnTheDialect) {
    std::vector<std::vector<std::string>> orders;
    for (const char* dialect : {"http://json-schema.org/draft-07/schema#",
                                "https://json-schema.org/draft/2020-12/schema"}) {
        const CompiledSchema schema(json::parse(std::string(R"({"$schema": ")") + dialect + R"(",
          "required": ["a"], "minProperties": 3, "additionalProperties": false,
          "propertyNames": {"maxLength": 1}, "properties": {}})"),
                                    "ties");
        std::vector<std::string> shown;
        for (const auto& issue : schema.validate(json::parse(R"({"bb": 1})"))) {
            shown.push_back(issue.pointer + " | " + issue.message);
        }
        orders.push_back(shown);
    }
    EXPECT_EQ(orders[0], orders[1]);
    EXPECT_GE(orders[0].size(), 3u);
}

// A default round-trips with its JSON type: it reaches the fingerprint, where 1 and 1.0 differ.
TEST(Schema, DefaultsKeepTheirJsonType) {
    const CompiledSchema schema(json::parse(R"({"properties": {
      "one": {"default": 1.0}, "whole": {"default": 1}, "big": {"default": 1e300},
      "zero": {"default": -0.0}, "huge": {"default": 18446744073709551615},
      "neg": {"default": -9223372036854775807}, "text": {"default": "a"},
      "list": {"default": [1, 2.5, null, true]}, "map": {"default": {"k": 1.0}}}})"),
                                "defaults");
    std::vector<SchemaIssue> issues;
    const json filled = schema.apply_defaults(json::object(), issues);
    EXPECT_TRUE(issues.empty());
    EXPECT_TRUE(filled.at("one").is_number_float());
    EXPECT_EQ(filled.at("one").get<double>(), 1.0);
    EXPECT_TRUE(filled.at("whole").is_number_integer());
    EXPECT_TRUE(filled.at("big").is_number_float());
    EXPECT_EQ(filled.at("big").get<double>(), 1e300);
    EXPECT_TRUE(filled.at("zero").is_number_float());
    EXPECT_TRUE(std::signbit(filled.at("zero").get<double>()));
    EXPECT_TRUE(filled.at("huge").is_number_unsigned());
    EXPECT_EQ(filled.at("huge").get<std::uint64_t>(), 18446744073709551615ull);
    EXPECT_EQ(filled.at("neg").get<std::int64_t>(), -9223372036854775807ll);
    EXPECT_EQ(filled.at("list").dump(), "[1,2.5,null,true]");
    EXPECT_TRUE(filled.at("map").at("k").is_number_float());
}

TEST(Schema, UuidFormatIsChecked) {
    for (const char* dialect : {"http://json-schema.org/draft-07/schema#",
                                "https://json-schema.org/draft/2020-12/schema"}) {
        SCOPED_TRACE(dialect);
        const CompiledSchema schema(json{{"$schema", dialect},
                                         {"type", "string"},
                                         {"format", "uuid"},
                                         {"allOf", {{{"maxLength", 40}}}}},
                                    "uuid");
        EXPECT_TRUE(schema.validate(json("123e4567-e89b-12d3-a456-426614174000")).empty());
        EXPECT_TRUE(schema.validate(json("123E4567-E89B-12D3-A456-426614174000")).empty());
        EXPECT_FALSE(schema.validate(json("123e4567e89b12d3a456426614174000")).empty());
        EXPECT_FALSE(schema.validate(json("not a uuid")).empty());
        EXPECT_FALSE(schema.validate(json(5)).empty()); // not a string
    }
    const CompiledSchema untyped(json::parse(R"({"format": "uuid"})"), "untyped");
    EXPECT_TRUE(untyped.validate(json(5)).empty()) << "a format applies to strings only";
}

