namespace {

std::string shown(const std::vector<SchemaIssue>& issues) {
    std::string text;
    for (const auto& issue : issues) {
        text += issue.pointer + " | " + issue.message + "\n";
    }
    return text;
}

// The same rule written for each dialect: the same first issue, and the same pointers.
void expect_same_first_issue(const char* draft07, const char* modern, const char* instance) {
    const CompiledSchema old_style(json::parse(std::string(R"({"$schema": "http://json-schema.org/draft-07/schema#",)") + draft07 + "}"), "d7");
    const CompiledSchema new_style(json::parse(std::string(R"({"$schema": "https://json-schema.org/draft/2020-12/schema",)") + modern + "}"), "2020");
    const auto first = old_style.validate(json::parse(instance));
    const auto second = new_style.validate(json::parse(instance));
    ASSERT_FALSE(first.empty()) << draft07;
    ASSERT_FALSE(second.empty()) << modern;
    EXPECT_EQ(first.front().pointer, second.front().pointer) << shown(first) << "--\n" << shown(second);
    EXPECT_EQ(first.size(), second.size()) << shown(first) << "--\n" << shown(second);
    std::vector<std::string> left, right;
    for (const auto& issue : first) left.push_back(issue.pointer);
    for (const auto& issue : second) right.push_back(issue.pointer);
    EXPECT_EQ(left, right);
    if (first.front().message != second.front().message) {
        ADD_FAILURE() << "first messages differ:\n" << shown(first) << "--\n" << shown(second);
    }
}

} // namespace

// Rules that the two dialects name differently report their first issue the same way (the order is
// the library's where the pointers are equal; these rules are the ones compared).
TEST(Schema, RenamedKeywordsGiveTheSameFirstIssue) {
    expect_same_first_issue(R"("dependencies": {"a": ["b", "c"]})", R"("dependentRequired": {"a": ["b", "c"]})",
                            R"({"a": 1})");
    expect_same_first_issue(R"("dependencies": {"a": {"required": ["b"]}})",
                            R"("dependentSchemas": {"a": {"required": ["b"]}})", R"({"a": 1})");
    expect_same_first_issue(R"("items": [{"type": "string"}], "additionalItems": false)",
                            R"("prefixItems": [{"type": "string"}], "items": false)", R"([1, 2])");
    expect_same_first_issue(R"("items": [{"type": "string"}], "additionalItems": {"type": "integer"})",
                            R"("prefixItems": [{"type": "string"}], "items": {"type": "integer"})",
                            R"(["a", "b"])");
    // `const` sorts between the two names (additionalItems < const < items); the issues land at
    // different pointers, so the order does not depend on the names.
    expect_same_first_issue(R"("items": [{}], "additionalItems": false, "const": [0])",
                            R"("prefixItems": [{}], "items": false, "const": [0])", R"([1, 2])");
    expect_same_first_issue(R"("definitions": {"n": {"type": "number"}}, "properties": {"p": {"$ref": "#/definitions/n"}})",
                            R"("$defs": {"n": {"type": "number"}}, "properties": {"p": {"$ref": "#/$defs/n"}})",
                            R"({"p": "x"})");
    // A failure nested under an applicator in one dialect and flat in the other.
    expect_same_first_issue(R"("type": "object", "properties": {"a": {"type": "integer"}}, "dependencies": {"a": ["z"]})",
                            R"("type": "object", "properties": {"a": {"type": "integer"}}, "dependentRequired": {"a": ["z"]})",
                            R"({"a": "x"})");
}

// The adapter reads the texts of three of jsoncons' messages (an `additionalProperties` that
// rejects a property, one that fails the schema of `additionalProperties`, and the pattern that
// stands for the uuid format) and the keyword names of the issues. The build asks for exactly
// jsoncons 1.10.0; this test fails when a library that words them otherwise gets in anyway.
TEST(Schema, LibraryMessageTextsTheAdapterReliesOn) {
    for (const char* dialect : {"http://json-schema.org/draft-07/schema#",
                                "https://json-schema.org/draft/2020-12/schema"}) {
        SCOPED_TRACE(dialect);
        const auto make = [&](const char* body) {
            return CompiledSchema(json::parse(std::string(R"({"$schema": ")") + dialect + R"(", )" + body + "}"), "text");
        };
        const CompiledSchema closed = make(R"("type": "object", "properties": {"a": {}}, "additionalProperties": false)");
        auto issues = closed.validate(json::parse(R"({"a": 1, "b/c": 2})"));
        ASSERT_EQ(issues.size(), 1u);
        EXPECT_EQ(issues[0].pointer, "/b~1c");
        EXPECT_EQ(issues[0].message, "property 'b/c' is not allowed");

        const CompiledSchema map = make(R"("additionalProperties": {"type": "integer"})");
        issues = map.validate(json::parse(R"({"k": "x"})"));
        ASSERT_EQ(issues.size(), 1u);
        EXPECT_EQ(issues[0].pointer, "/k");
        EXPECT_EQ(issues[0].message, "property 'k' is invalid");

        const CompiledSchema uuid = make(R"("format": "uuid")");
        issues = uuid.validate(json("abc"));
        ASSERT_EQ(issues.size(), 1u);
        EXPECT_EQ(issues[0].message, "String 'abc' is not a valid UUID");

        // Beside a pattern of the schema's own, the uuid check is an `allOf` branch, and neither the
        // `allOf` text nor the pattern text of the uuid shows.
        const CompiledSchema both = make(R"("type": "string", "pattern": "^[0-9a-f-]+$", "format": "uuid")");
        issues = both.validate(json("zzz"));
        ASSERT_EQ(issues.size(), 2u) << shown(issues);
        for (const auto& issue : issues) {
            EXPECT_EQ(issue.message.find("[0-9a-fA-F]"), std::string::npos) << issue.message;
            EXPECT_EQ(issue.message.find("all schemas"), std::string::npos) << issue.message;
        }
        EXPECT_NE(shown(issues).find("is not a valid UUID"), std::string::npos) << shown(issues);
        EXPECT_NE(shown(issues).find("does not match pattern '^[0-9a-f-]+$'"), std::string::npos)
            << shown(issues);
    }
}

// Draft-07 reads nothing beside a `$ref`, an `$id` included: it does not start a resource. Two
// schemas claim the identifier "inner": the first is a real resource that refers to itself in
// place, the second has the `$id` beside a `$ref` and is ignored by draft-07 (and by the library).
// A walk that took the second for the resource would not see the cycle, and the library, which
// follows the first, would overflow the stack.
TEST(Schema, DraftSevenIgnoresAnIdBesideARef) {
    const char* const body = R"("definitions": {
        "a_real": {"$id": "inner", "not": {"$ref": "inner"}},
        "z_ignored": {"$id": "inner", "$ref": "#/definitions/y"},
        "y": {"type": "string"}},
      "allOf": [{"$ref": "inner"}])";
    EXPECT_EQ(error_code_of([&] {
                  CompiledSchema(json::parse(std::string(R"({"$id": "https://example.com/root", )") + body + "}"),
                                 "d7");
              }),
              ErrorCode::SCHEMA_VIOLATION);
    // In 2020-12 both `$id`s are resources, the identifier is claimed twice, and the library refuses
    // the schema (or follows one of them); either way the call returns.
    const std::string modern = std::string(R"({"$schema": "https://json-schema.org/draft/2020-12/schema",
        "$id": "https://example.com/root", )") + body + "}";
    try {
        const CompiledSchema schema(json::parse(modern), "modern");
    } catch (const Error& error) {
        EXPECT_EQ(error.code(), ErrorCode::SCHEMA_VIOLATION);
    }
}

// Dynamic anchors of one name in two resources: only those in the dynamic scope count. A resource
// that the root never reaches does not make a schema cyclic.
TEST(Schema, DynamicAnchorsAreScopedByResource) {
    const CompiledSchema schema(json::parse(R"({
      "$schema": "https://json-schema.org/draft/2020-12/schema",
      "$id": "https://example.com/r1",
      "$defs": {
        "a": {"$dynamicAnchor": "x", "type": "string"},
        "r2": {"$id": "https://example.com/r2", "$dynamicAnchor": "x", "$ref": "https://example.com/r1"}},
      "allOf": [{"$dynamicRef": "#x"}]})"),
                                "scoped");
    EXPECT_TRUE(schema.validate(json("s")).empty());
    EXPECT_FALSE(schema.validate(json(5)).empty());
}

// ---------------------------------------------------------------------------------------------
// Stack use. The limits of ADR-0043: an instance nests 136 levels, applicators that apply to the
// same value chain 32 deep, a schema nests 128 levels of JSON. Every case runs with the stack of
// the threads that validation starts cut to half of what the formula gives (a test hook), and the
// work that stays on the caller's thread runs on a caller with 256 KiB, half of the 512 KiB that a
// secondary thread has on macOS: the formula and the inline budget therefore have a margin of two.

namespace {

constexpr int kInstanceLevels = 136;
constexpr int kChainLimit = 32;

struct HalfStack {
    HalfStack() { praenora::detail::set_stack_percent_for_testing(50); }
    ~HalfStack() { praenora::detail::reset_stack_tuning_for_testing(); }
};

template <typename Fn> void on_small_stack(Fn&& body) {
    praenora::detail::run_on_thread_with_stack(256 * 1024, std::forward<Fn>(body));
}

bool is_array_descent(const std::string& d) {
    return d == "items" || d == "prefixItems" || d == "contains" || d == "unevaluatedItems";
}

json descent_schema(const std::string& descent, const json& ref) {
    if (descent == "properties") return {{"properties", {{"kid", ref}}}};
    if (descent == "additionalProperties") return {{"additionalProperties", ref}};
    if (descent == "patternProperties") return {{"patternProperties", {{"^k", ref}}}};
    if (descent == "unevaluatedProperties") return {{"unevaluatedProperties", ref}};
    if (descent == "items") return {{"items", ref}};
    if (descent == "prefixItems") return {{"prefixItems", json::array({ref})}};
    if (descent == "contains") return {{"contains", ref}, {"minContains", 0}};
    if (descent == "unevaluatedItems") return {{"unevaluatedItems", ref}};
    return {{"dependentSchemas", {{"kid", {{"properties", {{"kid", ref}}}}}}}};
}

// `hops` in-place applicators of one kind around the descent; "not" counts two hops a wrapper.
json wrapped(const std::string& kind, int hops, json inner) {
    for (int i = 0; i < hops; ++i) {
        if (kind == "allOf") inner = json{{"allOf", json::array({inner})}};
        else if (kind == "anyOf") inner = json{{"anyOf", json::array({inner})}};
        else if (kind == "oneOf") inner = json{{"oneOf", json::array({inner})}};
        else if (kind == "not") inner = json{{"not", json{{"not", inner}}}};
        else if (kind == "if") inner = json{{"if", true}, {"then", inner}};
        else if (kind == "dependentSchemas") inner = json{{"dependentSchemas", {{"kid", inner}}}};
    }
    return inner;
}

// A recursive schema: the root refers to definition n, which is the wrapped descent and refers to
// itself through the descent. `hops` is the longest chain without the `$ref` that closes the loop.
json recursive_schema(const std::string& descent, const std::string& kind, int hops, bool dynamic = false) {
    const json ref = dynamic ? json{{"$dynamicRef", "#n"}} : json{{"$ref", "#/$defs/n"}};
    json n = wrapped(kind, hops, descent_schema(descent, ref));
    if (dynamic) {
        n["$dynamicAnchor"] = "n";
    }
    json schema = {{"$schema", "https://json-schema.org/draft/2020-12/schema"}, {"$defs", {{"n", n}}}};
    schema.update(dynamic ? json{{"$dynamicRef", "#n"}} : json{{"$ref", "#/$defs/n"}});
    return schema;
}

json nested_instance(const std::string& descent, int levels) {
    json instance = is_array_descent(descent) ? json::array() : json::object();
    for (int i = 0; i < levels; ++i) {
        instance = is_array_descent(descent) ? json::array({instance}) : json{{"kid", instance}};
    }
    return instance;
}

// Compiles `schema` and validates the deepest instance against it, on a caller with 256 KiB and
// with the stack of started threads halved.
void expect_worst_case(const json& schema, const std::string& descent, const char* what) {
    SCOPED_TRACE(what);
    HalfStack half;
    bool compiled = false;
    std::size_t issues = 99;
    on_small_stack([&] {
        const CompiledSchema compiled_schema(schema, "worst");
        compiled = true;
        issues = compiled_schema.validate(nested_instance(descent, kInstanceLevels)).size();
    });
    EXPECT_TRUE(compiled);
    EXPECT_EQ(issues, 0u);
}

} // namespace

// Every keyword that recurses into the instance, at 136 levels, on half the stack.
TEST(Schema, EveryDescendingKeywordFitsAtTheInstanceLimit) {
    for (const char* descent : {"properties", "additionalProperties", "patternProperties",
                                "unevaluatedProperties", "items", "prefixItems", "contains",
                                "unevaluatedItems", "dependentSchemas"}) {
        expect_worst_case(recursive_schema(descent, "allOf", 0), descent, descent);
    }
    expect_worst_case(recursive_schema("properties", "allOf", 0, true), "properties", "$dynamicRef");
}

// Every in-place applicator, chained to the limit, around a recursive schema, at 136 levels, on half
// the stack. The chain counts the `$ref` that closes the loop and, for `not`, two hops a wrapper.
TEST(Schema, EveryApplicatorChainedToTheLimitFitsAtTheInstanceLimit) {
    for (const char* kind : {"allOf", "anyOf", "oneOf", "if", "dependentSchemas"}) {
        expect_worst_case(recursive_schema("properties", kind, kChainLimit - 1), "properties", kind);
    }
    expect_worst_case(recursive_schema("properties", "not", (kChainLimit - 2) / 2), "properties", "not");
}

// The meta-schemas, as the target of a `$ref`, validate a schema-shaped instance 136 levels deep.
TEST(Schema, MetaSchemaReferencesFitAtTheInstanceLimit) {
    for (const char* dialect : {"http://json-schema.org/draft-07/schema#",
                                "https://json-schema.org/draft/2020-12/schema"}) {
        for (const char* shape : {"not", "items", "properties", "allOf"}) {
            SCOPED_TRACE(std::string(dialect) + " " + shape);
            HalfStack half;
            const int levels = std::string(shape) == "properties" || std::string(shape) == "allOf"
                                   ? (kInstanceLevels / 2)
                                   : kInstanceLevels;
            json instance = json::object();
            for (int i = 0; i < levels; ++i) {
                const std::string name = shape;
                instance = name == "not"     ? json{{"not", instance}}
                           : name == "items" ? json{{"items", instance}}
                           : name == "allOf" ? json{{"allOf", json::array({instance})}}
                                             : json{{"properties", {{"p", instance}}}};
            }
            std::size_t issues = 99;
            on_small_stack([&] {
                const CompiledSchema schema(json{{"$schema", dialect}, {"$ref", dialect}}, "meta");
                issues = schema.validate(instance).size();
            });
            EXPECT_EQ(issues, 0u);
        }
    }
}

// Schemas nested to the document limit compile on half the stack, whatever keyword nests them.
TEST(Schema, SchemasNestedToTheDocumentLimitCompileOnHalfTheStack) {
    struct Shape {
        const char* name;
        int levels; // schema levels that make 126 to 128 levels of JSON
    };
    for (const char* dialect : {"http://json-schema.org/draft-07/schema#",
                                "https://json-schema.org/draft/2020-12/schema"}) {
        for (const Shape& shape : {Shape{"items", 126}, Shape{"additionalProperties", 126},
                                   Shape{"properties", 62}, Shape{"allOf", kChainLimit - 2},
                                   Shape{"not", kChainLimit - 2}, Shape{"if", kChainLimit - 2}}) {
            SCOPED_TRACE(std::string(dialect) + " " + shape.name);
            HalfStack half;
            json schema = {{"type", "string"}};
            for (int i = 0; i < shape.levels; ++i) {
                const std::string name = shape.name;
                schema = name == "items"                ? json{{"items", schema}}
                         : name == "additionalProperties" ? json{{"additionalProperties", schema}}
                         : name == "allOf"              ? json{{"allOf", json::array({schema})}}
                         : name == "not"                ? json{{"not", schema}}
                         : name == "if"                 ? json{{"if", json::object()}, {"then", schema}}
                                                        : json{{"properties", {{"p", schema}}}};
            }
            schema["$schema"] = dialect;
            bool compiled = false;
            on_small_stack([&] {
                const CompiledSchema compiled_schema(schema, "nested");
                compiled = true;
            });
            EXPECT_TRUE(compiled);
        }
    }
}

// One past each limit is refused cleanly.
TEST(Schema, OnePastEachLimitIsRefusedCleanly) {
    on_small_stack([&] {
        const CompiledSchema schema(recursive_schema("properties", "allOf", 0), "limits");
        const auto issues = schema.validate(nested_instance("properties", kInstanceLevels + 1));
        ASSERT_EQ(issues.size(), 1u);
        EXPECT_NE(issues[0].message.find("nests deeper than"), std::string::npos) << issues[0].message;
        EXPECT_EQ(error_code_of([&] { CompiledSchema(recursive_schema("properties", "allOf", kChainLimit), "long chain"); }),
                  ErrorCode::SCHEMA_VIOLATION);
        json deep = {{"type", "string"}};
        for (int i = 0; i < 64; ++i) {
            deep = json{{"properties", {{"p", deep}}}};
        }
        EXPECT_EQ(error_code_of([&] { CompiledSchema(deep, "too deep"); }), ErrorCode::SCHEMA_VIOLATION);
    });
}

// The rewrites that the library gets (a wrapper that moves a default, the `allOf` of a uuid
// pattern) add hops to the user's chain: a chain at the limit with both still fits.
TEST(Schema, ChainAtTheLimitWithTheRewritesFitsOnHalfTheStack) {
    json inner = {{"type", "object"},
                  {"properties", {{"kid", {{"$ref", "#/$defs/n"}}},
                                  {"id", {{"type", "string"}, {"format", "uuid"}, {"pattern", "^."}}},
                                  {"gain", {{"$ref", "#/$defs/f"}}}}}};
    for (int i = 0; i < kChainLimit - 1; ++i) {
        inner = json{{"allOf", json::array({inner})}};
    }
    const json schema = {{"$schema", "https://json-schema.org/draft/2020-12/schema"},
                         {"$defs", {{"n", inner}, {"f", {{"type", "number"}, {"default", 0.5}}}}},
                         {"$ref", "#/$defs/n"}};
    HalfStack half;
    std::size_t issues = 99;
    json filled;
    on_small_stack([&] {
        const CompiledSchema compiled(schema, "rewrites");
        std::vector<SchemaIssue> found;
        filled = compiled.apply_defaults(nested_instance("properties", kInstanceLevels), found);
        issues = found.size();
    });
    EXPECT_EQ(issues, 0u);
    EXPECT_EQ(filled.at("gain"), 0.5);
}

// A thread that cannot be started is a resource error, not an issue of the instance and not a
// defect of the schema.
TEST(Schema, ThreadThatCannotBeStartedIsAResourceError) {
    json deep_schema = {{"type", "string"}};
    for (int i = 0; i < 40; ++i) {
        deep_schema = json{{"items", deep_schema}};
    }
    praenora::detail::set_thread_failure_for_testing(true);
    EXPECT_EQ(error_code_of([&] { CompiledSchema(deep_schema, "deep"); }), ErrorCode::RESOURCE_EXHAUSTED);
    praenora::detail::set_thread_failure_for_testing(false);
    const CompiledSchema recursive(recursive_schema("properties", "allOf", 0), "recursive");
    praenora::detail::set_thread_failure_for_testing(true);
    EXPECT_EQ(error_code_of([&] { recursive.validate(nested_instance("properties", kInstanceLevels)); }),
              ErrorCode::RESOURCE_EXHAUSTED);
    // A shallow instance stays on the caller's thread and needs none.
    EXPECT_TRUE(recursive.validate(nested_instance("properties", 3)).empty());
    praenora::detail::set_thread_failure_for_testing(false);
    EXPECT_TRUE(recursive.validate(nested_instance("properties", kInstanceLevels)).empty());
}

// The work that stays on the caller's thread fits half of a macOS secondary thread: for every
// recursing keyword and every kind of applicator, the deepest instance whose estimate is still
// inside the inline budget runs on a caller with 256 KiB.
TEST(Schema, WorkWithinTheInlineBudgetFitsAHalfThread) {
    const std::size_t budget = praenora::detail::stack_inline_budget_for_testing();
    const auto run_largest = [&](const json& schema, const std::string& descent, const char* what) {
        SCOPED_TRACE(what);
        std::size_t issues = 99;
        int levels_run = 0;
        on_small_stack([&] {
            const CompiledSchema compiled(schema, "inline");
            int levels = 1;
            while (levels < kInstanceLevels &&
                   compiled.stack_estimate(nested_instance(descent, levels + 1)) <= budget) {
                ++levels;
            }
            levels_run = levels;
            issues = compiled.validate(nested_instance(descent, levels)).size();
        });
        EXPECT_EQ(issues, 0u);
        EXPECT_GE(levels_run, 1);
    };
    for (const char* descent : {"properties", "additionalProperties", "patternProperties",
                                "unevaluatedProperties", "items", "prefixItems", "contains",
                                "unevaluatedItems", "dependentSchemas"}) {
        run_largest(recursive_schema(descent, "allOf", 0), descent, descent);
    }
    for (const char* kind : {"allOf", "anyOf", "oneOf", "if", "dependentSchemas"}) {
        for (const int hops : {1, 4, 12}) {
            run_largest(recursive_schema("properties", kind, hops), "properties", kind);
        }
    }
    run_largest(recursive_schema("properties", "not", 3), "properties", "not");
    run_largest(recursive_schema("properties", "allOf", 0, true), "properties", "$dynamicRef");
}

// The real messages of the repository stay on the caller's thread: the estimate of every valid
// fixture document that is a message (envelopes, invocations, results, errors) and of a realistic
// envelope carrying an observation batch of 1,000 rows is inside the inline budget.
TEST(Schema, RealMessagesStayOnTheCallersThread) {
    const std::size_t budget = praenora::detail::stack_inline_budget_for_testing();
    const auto& registry = praenora::detail::SchemaRegistry::builtin();
    const auto semver = [](const char* v) { return praenora::detail::parse_semver(v); };
    const fs::path root = praenora::test::utf8_path(PRAENORA_TEST_SOURCE_DIR) / "tests/fixtures/documents/valid";
    int checked = 0;
    for (const char* kind : {"pmp-envelope", "pmp-invocation", "pmp-result", "pmp-error", "pmp-create",
                             "pmp-initialize", "pmp-describe"}) {
        for (const auto& entry : fs::directory_iterator(root / kind)) {
            if (entry.path().extension() != ".json") {
                continue;
            }
            std::ifstream in(entry.path(), std::ios::binary);
            const json document = json::parse(in);
            const auto& schema = registry.for_kind(kind, semver("0.1.0"));
            EXPECT_LE(schema.stack_estimate(document), budget) << entry.path().string();
            ++checked;
        }
    }
    EXPECT_GT(checked, 5);
    json batch = {{"window", {{"start", 0}, {"end", 1000}}}, {"time_unit", "h"}, {"observations", json::array()}};
    for (int i = 0; i < 1000; ++i) {
        batch["observations"].push_back({{"series_id", "p1"}, {"variable_id", "lactate"}, {"time", i * 0.5}, {"value", 1.0}, {"unit", "mmol/L"}});
    }
    const json envelope = {{"pmp_version", "0.1.0"}, {"id", "x:3:y"}, {"type", "pmp.observation-batch"},
                           {"type_version", "0.1.0"}, {"source", "s"}, {"tick", 3}, {"logical_time", 4.0},
                           {"data", batch}};
    EXPECT_LE(registry.for_kind("pmp-envelope", semver("0.1.0")).stack_estimate(envelope), budget);
}
